const { useEffect, useId, useRef, useState } = React;

const MIN_ZOOM = 0.1;
const MAX_ZOOM = 10;
const STEP = 1.1;
const INITIAL_VIEW = { minX: 0, minY: 0, zoom: 1 };
const SHAPES = [
  { kind: "rect", x: 100, y: 100, width: 200, height: 100, fill: "fill-tag-1-soft", stroke: "stroke-tag-1", label: "rect (100, 100)" },
  { kind: "circle", cx: 460, cy: 150, r: 60, fill: "fill-tag-2-soft", stroke: "stroke-tag-2", label: "circle (460, 150)" },
  { kind: "rect", x: -260, y: 260, width: 160, height: 120, fill: "fill-tag-3-soft", stroke: "stroke-tag-3", label: "rect (-260, 260)" },
  { kind: "circle", cx: 240, cy: 420, r: 40, fill: "fill-tag-4-soft", stroke: "stroke-tag-4", label: "circle (240, 420)" },
];

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const fmt = value => String(Number(value.toFixed(2)));

const Row = ({ label, children }) => (
  <>
    <dt className="text-tau-sm text-ink-3">{label}</dt>
    <dd className="m-0 min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">{children}</dd>
  </>
);

const Component = () => {
  const gridId = useId();
  const stageRef = useRef(null);
  const dragRef = useRef(null);
  const [size, setSize] = useState({ width: 0, height: 0 });
  const [view, setView] = useState(INITIAL_VIEW);
  const [followPointer, setFollowPointer] = useState(true);
  const [pointer, setPointer] = useState(null);
  const [anchor, setAnchor] = useState(null);
  const [lastStep, setLastStep] = useState(null);
  const [dragging, setDragging] = useState(false);

  // 原生 wheel 监听里读最新值
  const viewRef = useRef(view);
  viewRef.current = view;
  const followRef = useRef(followPointer);
  followRef.current = followPointer;

  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    const measure = () => {
      const { width, height } = stage.getBoundingClientRect();
      setSize({ width, height });
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(stage);
    return () => observer.disconnect();
  }, []);

  // offsetX / offsetY：缩放中心距画布左上角的像素距离
  const zoomAt = (offsetX, offsetY, factor) => {
    const { minX, minY, zoom } = viewRef.current;
    const newZoom = clamp(zoom * factor, MIN_ZOOM, MAX_ZOOM);
    if (newZoom === zoom) return;
    const centerX = followRef.current ? offsetX : 0;
    const centerY = followRef.current ? offsetY : 0;
    const newMinX = minX + centerX * (1 / zoom - 1 / newZoom);
    const newMinY = minY + centerY * (1 / zoom - 1 / newZoom);
    setView({ minX: newMinX, minY: newMinY, zoom: newZoom });
    setAnchor({ x: minX + centerX / zoom, y: minY + centerY / zoom });
    setLastStep({ type: "zoom", minX, minY, zoom, newZoom, offsetX: centerX, offsetY: centerY, newMinX, newMinY });
  };

  // React 的 onWheel 是被动监听，无法阻止页面滚动，这里用原生监听
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    const onWheel = event => {
      event.preventDefault();
      const rect = stage.getBoundingClientRect();
      zoomAt(event.clientX - rect.left, event.clientY - rect.top, event.deltaY < 0 ? STEP : 1 / STEP);
    };
    stage.addEventListener("wheel", onWheel, { passive: false });
    return () => stage.removeEventListener("wheel", onWheel);
  }, []);

  const localPoint = event => {
    const rect = stageRef.current.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  };

  const onPointerDown = event => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture?.(event.pointerId);
    dragRef.current = { x: event.clientX, y: event.clientY, minX: view.minX, minY: view.minY };
    setDragging(true);
  };
  const onPointerMove = event => {
    setPointer(localPoint(event));
    const start = dragRef.current;
    if (!start) return;
    const offsetX = event.clientX - start.x;
    const offsetY = event.clientY - start.y;
    const newMinX = start.minX - offsetX / view.zoom;
    const newMinY = start.minY - offsetY / view.zoom;
    setView(current => ({ ...current, minX: newMinX, minY: newMinY }));
    setLastStep({ type: "drag", minX: start.minX, minY: start.minY, zoom: view.zoom, offsetX, offsetY, newMinX, newMinY });
  };
  const endDrag = () => {
    dragRef.current = null;
    setDragging(false);
  };

  const reset = () => {
    setView(INITIAL_VIEW);
    setAnchor(null);
    setLastStep(null);
  };

  const viewWidth = size.width / view.zoom;
  const viewHeight = size.height / view.zoom;
  const viewBox = `${fmt(view.minX)} ${fmt(view.minY)} ${fmt(viewWidth)} ${fmt(viewHeight)}`;
  const pointerInSvg = pointer && { x: view.minX + pointer.x / view.zoom, y: view.minY + pointer.y / view.zoom };
  const unit = 1 / view.zoom;

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div
          ref={stageRef}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          onPointerLeave={() => setPointer(null)}
          className={`relative h-[300px] touch-none select-none overflow-hidden rounded-tau-md border border-line-1 ${dragging ? "cursor-grabbing" : "cursor-grab"}`}
        >
          <svg width="100%" height="100%" viewBox={size.width ? viewBox : undefined} className="block">
            <defs>
              <pattern id={gridId} width="40" height="40" patternUnits="userSpaceOnUse">
                <circle cx="0" cy="0" r={1.5 * unit} className="fill-line-1" />
              </pattern>
            </defs>
            <rect x="-20000" y="-20000" width="40000" height="40000" fill={`url(#${gridId})`} />
            <line x1="-20000" y1="0" x2="20000" y2="0" vectorEffect="non-scaling-stroke" className="stroke-line-1" />
            <line x1="0" y1="-20000" x2="0" y2="20000" vectorEffect="non-scaling-stroke" className="stroke-line-1" />
            <text x={6 * unit} y={-6 * unit} fontSize={12 * unit} className="fill-ink-3 font-tau-mono">
              (0, 0)
            </text>
            {SHAPES.map(shape => (
              <g key={shape.label}>
                {shape.kind === "rect" ? (
                  <rect x={shape.x} y={shape.y} width={shape.width} height={shape.height} rx="8" strokeWidth="1.5" vectorEffect="non-scaling-stroke" className={`${shape.fill} ${shape.stroke}`} />
                ) : (
                  <circle cx={shape.cx} cy={shape.cy} r={shape.r} strokeWidth="1.5" vectorEffect="non-scaling-stroke" className={`${shape.fill} ${shape.stroke}`} />
                )}
                <text
                  x={shape.kind === "rect" ? shape.x + 10 : shape.cx - shape.r}
                  y={shape.kind === "rect" ? shape.y + 22 : shape.cy + shape.r + 20}
                  fontSize="13"
                  className="fill-ink-2 font-tau-mono"
                >
                  {shape.label}
                </text>
              </g>
            ))}
            {anchor && (
              <g className="pointer-events-none">
                <circle cx={anchor.x} cy={anchor.y} r={7 * unit} fill="none" strokeWidth="1.5" vectorEffect="non-scaling-stroke" className="stroke-accent" />
                <circle cx={anchor.x} cy={anchor.y} r={2 * unit} className="fill-accent" />
              </g>
            )}
          </svg>
          <span className="pointer-events-none absolute bottom-2 left-2 rounded-tau-sm bg-surface px-1.5 py-0.5 text-tau-sm text-ink-3 shadow-card">
            拖拽平移，滚轮缩放
          </span>
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
            <Row label="viewBox">{viewBox}</Row>
            <Row label="zoom">{view.zoom.toFixed(2)}</Row>
            <Row label="1px 等于">{fmt(unit)} 个 SVG 单位</Row>
            <Row label="鼠标（像素）">{pointer ? `(${Math.round(pointer.x)}, ${Math.round(pointer.y)})` : "—"}</Row>
            <Row label="鼠标（SVG）">{pointerInSvg ? `(${fmt(pointerInSvg.x)}, ${fmt(pointerInSvg.y)})` : "—"}</Row>
          </dl>
          <div className="flex min-w-0 flex-col gap-1 rounded-tau-md border border-line-1 px-3 py-2.5">
            <span className="text-tau-sm text-ink-3">{lastStep ? (lastStep.type === "drag" ? "上一步：拖拽" : "上一步：缩放") : "上一步：无"}</span>
            {lastStep?.type === "drag" && (
              <code className="min-w-0 break-all font-tau-mono text-tau-sm text-ink-2">
                newMinX = {fmt(lastStep.minX)} − {fmt(lastStep.offsetX)} / {fmt(lastStep.zoom)} = {fmt(lastStep.newMinX)}
                <br />
                newMinY = {fmt(lastStep.minY)} − {fmt(lastStep.offsetY)} / {fmt(lastStep.zoom)} = {fmt(lastStep.newMinY)}
              </code>
            )}
            {lastStep?.type === "zoom" && (
              <code className="min-w-0 break-all font-tau-mono text-tau-sm text-ink-2">
                newMinX = {fmt(lastStep.minX)} + {fmt(lastStep.offsetX)} × (1/{fmt(lastStep.zoom)} − 1/{fmt(lastStep.newZoom)}) = {fmt(lastStep.newMinX)}
                <br />
                newMinY = {fmt(lastStep.minY)} + {fmt(lastStep.offsetY)} × (1/{fmt(lastStep.zoom)} − 1/{fmt(lastStep.newZoom)}) = {fmt(lastStep.newMinY)}
              </code>
            )}
            {!lastStep && <span className="text-tau-sm text-ink-3">拖动画布或滚动滚轮后，这里代入实际数值</span>}
          </div>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Switch checked={followPointer} onCheckedChange={setFollowPointer} label="以鼠标位置为缩放中心" size="sm" />
        <div className="ml-auto flex flex-wrap items-center gap-2">
          <ui.Button variant="secondary" size="sm" icon={icons.ZoomOut} onClick={() => zoomAt(size.width / 2, size.height / 2, 1 / STEP)}>
            缩小
          </ui.Button>
          <ui.Button variant="secondary" size="sm" icon={icons.ZoomIn} onClick={() => zoomAt(size.width / 2, size.height / 2, STEP)}>
            放大
          </ui.Button>
          <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={reset}>
            重置视图
          </ui.Button>
        </div>
      </div>
      <p className="m-0 text-tau-sm text-ink-3">
        {followPointer ? "圆环标出缩放中心：缩放前后它始终停在同一位置。" : "关闭后只改视口大小、不调整左上角，缩放总以画布左上角为中心，鼠标下的点会漂走。"}
      </p>
    </div>
  );
};
